 static int checks;static BindingFlags f=BindingFlags.NonPublic|BindingFlags.Instance;
 static void Check(bool yes,string message){checks++;if(!yes)throw new Exception(message);}
 static void Put(object o,string n,object v)=>o.GetType().GetField(n,f).SetValue(o,v);
 static T Get<T>(object o,string n)=>(T)o.GetType().GetField(n,f).GetValue(o);
 static object Call(object o,string n,params object[] a)=>o.GetType().GetMethod(n,f).Invoke(o,a);
 static GameFlow Game()
 {
  var root=new GameObject("test player");var p=root.AddComponent<WolfMotor>();var body=root.AddComponent<NativeAmaterasu>();Call(body,"Awake");
  var g=new GameFlow{Player=p,Panel="",Health=100,Energy=80,Stamina=100,InTrial=true};p.game=g;p.Grounded=true;var combat=root.AddComponent<WolfCombat>();g.Combat=combat;combat.game=g;combat.motor=p;combat.spear=new WeaponDefinition();combat.sundial=new WeaponDefinition();Put(combat,"nativeBody",body);combat.backSocket=body.CreateBackSocket();Put(g.Audio,"effects",new AudioSource());return g;
 }
 static EnemyBrain Enemy(GameFlow g,string id="heavy",float hp=30)
 {var e=new EnemyBrain();if(id=="boss"){e.game=g;e.definition=new EnemyDefinition{id=id,hp=hp,damage=1};e.Hp=e.MaxHp=hp;Put(e,"motor",new CharacterController());}else e.Init(g,new EnemyDefinition{id=id,hp=hp,damage=1,scale=1,visual=new GameObject("test enemy")});g.Enemies.Add(e);return e;}
