   string evolved=OriginalWeaponEvolution.EvolvedId(entry.id);Check(!OriginalWeaponCatalog.Owns(p,entry.id)&&OriginalWeaponCatalog.Owns(p,evolved),"Base not replaced");var powered=OriginalWeaponCatalog.Find(evolved);Check(powered.resource==entry.resource&&powered.family==entry.family,"Awakening substitutes wrong native mesh");
   var normal=OriginalWeaponCatalog.Definition(entry,new WeaponDefinition(),new WeaponDefinition(),p);var awake=OriginalWeaponCatalog.Definition(powered,new WeaponDefinition(),new WeaponDefinition(),p);Check(awake.light[0].damage>normal.light[0].damage&&awake.light[0].range>normal.light[0].range,"Awakening lacks strength/reach");
   for(int rank=0;rank<5;rank++)Check(AwakeningProgress.Upgrade(p,evolved),"Rank cannot be bought");Check(!AwakeningProgress.Upgrade(p,evolved),"Rank cap bypassed");var ranked=OriginalWeaponCatalog.Definition(powered,new WeaponDefinition(),new WeaponDefinition(),p);Check(ranked.light[0].damage>awake.light[0].damage && ranked.light[0].range>awake.light[0].range,"Ranks do not affect actual strikes");Check(ProgressionRules.Validate(p),"Evolved save rejected");
  }
  p.equipped="speare";for(int i=0;i<15;i++){p.equipped=OriginalWeaponCatalog.Next(p);Check(OriginalWeaponEvolution.IsAwakened(p.equipped),"Q returns replaced base");}Check(p.equipped=="speare","Catalogue cycling skips an awakened weapon");
  var poor=new ProfileData{owned=new[]{"spear","wp20e"},equipped="wp20e",coins=0};Check(!AwakeningProgress.Upgrade(poor,"wp20e")&&AwakeningProgress.Rank(poor,"wp20e")==0,"Insufficient coins still upgrades");
  var live=Game();live.Profile.owned=new[]{"spear","wp20"};live.Profile.equipped="wp20";var progress=AwakeningProgress.Get(live.Profile,"wp20");progress.hits=24;progress.charged=2;AwakeningProgress.Record(live,"hit",true);Check(live.Profile.equipped=="wp20e"&&Get<bool>(live.Combat,"awakeningEquipPending"),"Challenge does not safely queue attachment update");
  live.InTrial=false;int previous=progress.hits;AwakeningProgress.Record(live,"hit",true);Check(progress.hits==previous,"Training/outside fight farms challenge progress");
  var rest=Game();rest.InTrial=false;rest.Player.transform.position=HomeBlessings.Fire;rest.Stamina=5;var hearth=new HomeBlessings{game=rest};hearth.SitByFire();Check(rest.MaxStamina==150&&rest.Stamina==150,"Hearth does not fill real enlarged stamina property");HomeBlessings.BedBonus(rest.Profile,HomeBlessings.Now);Check(rest.MaxHealth==150&&rest.MaxStamina==150,"Bed does not increase actual health and stamina maxima");Check(HomeBlessings.Status(rest.Profile,HomeBlessings.Now).Contains("+50"),"Blessing invisible in HUD");rest.Profile.bedBlessingUntil=rest.Profile.fireBlessingUntil=0;Check(rest.MaxStamina==100,"Expired stamina remains");
  HeavenPhysicsFixture.hits=new[]{new RaycastHit{collider=new Collider{name="Heaven garden ground upper terrace"},point=HeavenlyGarden.Centre+Vector3.up*8}};var portal=new HeavenReturnPortal{game=rest};portal.transform.position=HeavenlyGarden.Centre+new Vector3(0,0,-26.5f);rest.Player.transform.position=portal.transform.position+Vector3.up*.05f;Call(portal,"Update");Check(rest.homeReturns==1,"Gate-owned return fails under an upper tier");HeavenPhysicsFixture.hits=Array.Empty<RaycastHit>();
  foreach(int fps in new[]{15,30,60,120})
  {
   var g=Game();g.Player.GetComponent<NativeAmaterasu>().ApplyPowerForm(2);g.Ultimate=new ShiranuiUltimate{game=g};Enemy(g);Enemy(g);Check(g.Ultimate.Begin()&&g.Player.Locked,"U cannot begin in third form");Check(!g.Ultimate.Begin(),"Ultimate re-enters itself");Time.unscaledDeltaTime=1f/fps;for(int i=0;i<fps*7;i++)Call(g.Ultimate,"Update");Check(!g.Ultimate.Playing&&!g.Player.Locked&&g.Enemies.All(e=>e.Dead),"Ultimate fails to clear arena/restore control");Check(!g.Ultimate.Begin()&&g.Ultimate.Used,"Ultimate refreshes within same fight");g.Ultimate.ResetFight();g.Enemies.Clear();Enemy(g);Check(g.Ultimate.Begin(),"New fight cannot use ultimate");g.Ultimate.Skip();Check(!g.Ultimate.Playing&&!g.Player.Locked&&g.Enemies[0].Dead,"Skip loses blast or locks player");g.Ultimate.ResetFight();g.Player.GetComponent<NativeAmaterasu>().ApplyPowerForm(1);g.Enemies.Clear();Enemy(g);Check(!g.Ultimate.Begin(),"Second form can use third-form ultimate");
  }
