  var hitGame=Game();hitGame.Profile.equipped="wp29e";hitGame.Profile.owned=new[]{"spear","wp29e"};hitGame.Combat.Equip();var victim=Enemy(hitGame,"heavy",1000);Call(hitGame.Combat,"Begin",new Strike{clip="NativeAttack_524",duration=1,damage=10,range=5,start=.2f,end=.6f});Call(hitGame.Combat,"DamageEnemy",victim,Vector3.forward);Check(victim.Hp<victim.MaxHp&&AwakeningProgress.Get(hitGame.Profile,"wp29").charged==1,"Actual charged strike fails damage/progress");Time.deltaTime=.2f;for(int i=0;i<50;i++)Call(hitGame.Combat,"Update");Check(!hitGame.Combat.Busy,"Charged attack stays frozen/busy");
  var zap=Game();zap.Profile.equipped="wp29e";zap.Profile.owned=new[]{"spear","wp29e"};zap.Combat.Equip();var zapped=Enemy(zap,"heavy",1000);zapped.transform.position=new Vector3(12,0,0);Camera.Projection=v=>new Vector3(400+v.x*10,200+v.y*10,1);var brush=new CelestialBrush{game=zap};var stroke=Get<List<Vector2>>(brush,"stroke");var world=Get<List<Vector3>>(brush,"world");var first=(Vector2)Camera.main.WorldToScreenPoint(zap.Combat.LightningSource);var last=(Vector2)Camera.main.WorldToScreenPoint(zapped.transform.position+Vector3.up*.6f);for(int i=0;i<12;i++){stroke.Add(Vector2.Lerp(first,last,i/11f));world.Add(Vector3.Lerp(zap.Combat.LightningSource,zapped.transform.position,i/11f));}float hp=zapped.Hp;Call(brush,"Resolve");Check(zapped.Hp<hp&&zap.Energy==60,"Weapon-to-enemy brush connection fails actual zap/ink cost");Camera.Projection=v=>v;
  var arcRoot=new GameObject("Arc endpoint audit");ThunderPainting.Arc(arcRoot.transform,new Vector3(0,12,0),new Vector3(0,.04f,0),.32f,.3f,1);var core=GameObject.created.Last(o=>o.name=="Lightning core").GetComponent<LineRenderer>();Check(core.positions[0].y==12&&Math.Abs(core.positions[16].y-.04f)<.0001f,"Charged bolt stops above enemy/floor");
  var frostGame=Game();var frozen=Enemy(frostGame);Time.time=100;frozen.Freeze(.9f);Check(frozen.Frozen&&frozen.VisualStunned,"Charged ice does not freeze ordinary enemies");Time.time=101;Check(!frozen.Frozen,"Freeze does not expire");frozen.Freeze(.9f);Check(!frozen.Frozen,"Repeated ice can permanently freeze-lock");Time.time=104;frozen.Freeze(.9f);Check(frozen.Frozen,"Freeze never recovers from immunity window");Time.time=0;
  Console.WriteLine("PASS "+checks+" real catalogue, upgrades/save migration, combat contact, stamina pools, obstructed-height portal and ultimate normal/skip/boss-phase cases. Engine doubles; Unity playback unverified.");
 }
